/**
 * Surveyed tactile WARNING strips, bundled per district.
 *
 * Generated by the data pipeline's build_js_graphs.py from the Transport Department's
 * "Tactile Warning Stripe Line" layer. These are the blistered / lozenge-laid
 * strips at a decision point: the top and bottom of stairs, a platform edge, a
 * crossing.
 *
 * WHY THESE AND NOT THE GUIDE PATHS: the TD tactile GUIDE path layer is the
 * directional strip a cane follows, and it is far too sparse to route on or
 * weight by — joining it to the CSDI network labelled 7 of 4,995 edges in
 * Central (0.14%) and 1 of 5,034 in Tsim Sha Tsui (0.02%). The WARNING layer is
 * 4.6x longer (257.5 km vs 56.3 km) and ~19x better matched to the network
 * (2.7% of edges), and it marks exactly the places a blind pedestrian needs to
 * be told about.
 *
 * WHAT THIS CANNOT DO: it detects surveyed decision points, NOT arbitrary
 * obstacles. A construction barricade on a footway with no warning strip is
 * invisible to it. Do not present it as general obstacle detection.
 */

import hazards from '../data/network/hazards';

/** A route point within this many metres of a strip is at that decision point. */
export const HAZARD_PROXIMITY_M = 3.0;

/** Strikes closer than this are the same physical decision point. */
export const HAZARD_CLUSTER_M = 8.0;

/** Warning-stripe segments for a district, or an empty array. */
export function hazardsFor(districtId) {
  if (!districtId) return [];
  return hazards[districtId] || [];
}

/** Districts that have hazard data bundled. */
export function hazardAreas() {
  return Object.keys(hazards);
}
